func htLine(wd *port.Cells, ln *port.Cells, et *port.Cells, b []byte, page int32, x0 int32, y0 int32, x1 int32, y1 int32, size int32, style int32) int32 {
	// Append one upright line on `page`: the words of the UTF-8 text b (split at spaces) with the size and the
	// style bits, the line's box and a baseline 2 pt above its bottom. Answers the line's index.
	var w0 int32 = evidence.WdCount(wd)
	var n int32 = port.BlobLen(b)
	var at int32 = evidence.LnCount(ln)
	var s int32 = 0
	var k int32 = 0
	for k <= n {
		if (k == n) || (port.BlobU8(b, k) == 32) {
			if k > s {
				var ts int32 = port.CellsLen(et)
				model.TextAppendUtf8(et, b, s, k)
				var tl int32 = port.CellsLen(et) - ts
				var r int32 = evidence.WdNew(wd, page, x0, y0, x1, y1, x0, y1-200, x1, y1-200, 0, 0, ts, tl, -1, -1, -1)
				evidence.WdSet(wd, r, evidence.WfSize(), size)
				evidence.WdSet(wd, r, evidence.WfFont(), 0)
				evidence.WdSet(wd, r, evidence.WfStyle(), style)
			}
			s = k + 1
		}
		k += 1
	}
	evidence.LnNew(ln, page, x0, y0, x1, y1, x0, y1-200, x1, y1-200, 0, 0, w0, evidence.WdCount(wd)-w0)
	return at
}

