func htBrief(t *strings.Builder, nodes *port.Cells, text *port.Cells) int32 {
	// The shape of the Model: every node but the root, in id order: S<level> a section, H<level>:<text> a
	// heading, P a paragraph, B<page> a milestone; each ended by `;`.
	var n int32 = model.NodeCount(nodes)
	var i int32 = 1
	var k int32 = 0
	var kind int32 = 0
	var s int32 = 0
	for i < n {
		kind = model.NodeKind(nodes, i)
		if kind == model.NkSection() {
			port.TextCp(t, 83)
			port.TextI32(t, model.NodeSub(nodes, i))
		}
		if kind == model.NkHeading() {
			port.TextCp(t, 72)
			port.TextI32(t, model.NodeSub(nodes, i))
			port.TextCp(t, 58)
			s = model.NodeTextStart(nodes, i)
			k = 0
			for k < model.NodeTextLen(nodes, i) {
				port.TextCp(t, model.TextAt(text, s+k))
				k += 1
			}
		}
		if kind == model.NkParagraph() {
			port.TextCp(t, 80)
		}
		if kind == model.NkBreak() {
			port.TextCp(t, 66)
			port.TextI32(t, model.NodeSub(nodes, i))
		}
		port.TextCp(t, 59)
		i += 1
	}
	return 0
}

