func TestAnOutlineOverrulesTheSequence(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var sf *port.Cells = port.NewCells()
	var sc *port.Cells = port.NewCells()
	var hc *port.Cells = port.NewCells()
	var ws *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var pr *port.Cells = port.NewCells()
	var ptxt *port.Cells = port.NewCells()
	var ttl *port.Cells = port.NewCells()
	var y int32 = 5000
	// Alpha (12 pt bold) comes first, Beta (16 pt bold) after: the sequence says Alpha is the parent
	htHeading(wd, ln, et, port.TextBlob("Alpha"), y, 1200, 1)
	y += 2300
	y = htBody(wd, ln, et, 1, y, 2)
	y += 900
	htHeading(wd, ln, et, port.TextBlob("Beta"), y, 1600, 1)
	y += 2500
	y = htBody(wd, ln, et, 1, y, 2)
	y += 900
	htHeading(wd, ln, et, port.TextBlob("Alpha"), y, 1200, 1)
	y += 2300
	y = htBody(wd, ln, et, 1, y, 2)
	y += 900
	htHeading(wd, ln, et, port.TextBlob("Beta"), y, 1600, 1)
	y += 2500
	y = htBody(wd, ln, et, 1, y, 2)
	port.AssertEq(emonT, htRun(wd, ln, et, sf, sc, hc, ws, tmp, pr, ptxt), 4, "four headings")
	port.AssertEq(emonT, heading.HdLevel(hc, 0), 1, "without a prior the first class is the top")
	port.AssertEq(emonT, heading.HdLevel(hc, 3), 2, "and the other under it")
	// an outline says Beta is at depth 0 and Alpha at depth 1
	model.TextAppendUtf8(ttl, port.TextBlob("Beta"), 0, 4)
	heading.HdPriorAdd(pr, ptxt, 2, 0, 4, ttl, 1, 800)
	model.TextAppendUtf8(ttl, port.TextBlob("Alpha"), 0, 5)
	heading.HdPriorAdd(pr, ptxt, 2, 4, 5, ttl, 2, 800)
	port.AssertEq(emonT, htRun(wd, ln, et, sf, sc, hc, ws, tmp, pr, ptxt), 4, "four headings")
	port.AssertEq(emonT, heading.HdLevel(hc, 0), 2, "now Alpha is the inner heading")
	port.AssertEq(emonT, heading.HdLevel(hc, 3), 1, "and Beta the outer, as the author's outline says")
}

func TestAnOutlineRowIsAPrior(emonT *testing.T) {
	var ol *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var pr *port.Cells = port.NewCells()
	var ptxt *port.Cells = port.NewCells()
	var i int32 = 0
	for i < 24 {
		port.CellsPush(ol, 0)
		i += 1
	}
	model.TextAppendUtf8(txt, port.TextBlob("xxIntroduction"), 0, 14)
	port.CellsSet(ol, 0, 2)
	port.CellsSet(ol, 5, 2)
	port.CellsSet(ol, 6, 12)
	port.AssertEq(emonT, heading.HdPriorOutline(ol, txt, pr, ptxt), 1, "one row read")
	port.AssertEq(emonT, port.CellsAt(pr, 1), 12, "its title is twelve code points")
	port.AssertEq(emonT, port.CellsAt(pr, 2), 3, "at depth 2, so level 3")
	port.AssertEq(emonT, port.CellsAt(pr, 3), 2, "from an outline")
	port.AssertEq(emonT, port.CellsAt(pr, 4), 800, "with the weight of a healthy outline")
	port.AssertEq(emonT, port.CellsLen(ptxt), 12, "and its text copied")
}

func htGolden(pdf []byte, t *strings.Builder, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pg *port.Cells, wd *port.Cells, ln *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, pages *port.Cells, ledger *port.Cells, layout *port.Cells, ord *port.Cells, raw *port.Cells, tmp *port.Cells, fr *port.Cells, gp *port.Cells, mst *port.Cells, sf *port.Cells, sc *port.Cells, hc *port.Cells, ws *port.Cells, tmp2 *port.Cells, pr *port.Cells, ptxt *port.Cells) int32 {
	// PDF -> content -> headings -> paragraphs and sections -> Model -> pretty JSON; answer 0 when every step
	// answered 0, else a code naming the step (1 open, 2 content, 3 the Model's check). The JSON is `t`.
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(mk, 0)
	port.CellsDrop(fnt, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	var src *port.Src = port.SrcOfBlob(pdf)
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var o int32 = pdfdoc.PdOpen(src, ar, dc, a, b, st)
	if o != 0 {
		return 1
	}
	if pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx) != 0 {
		return 2
	}
	heading.HdAnalyze(wd, ln, et, gl, sf, sc, hc, ws, tmp2, pr, ptxt)
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	para.PaPages(pg, pages)
	var np int32 = port.CellsLen(pages) / 16
	htPa(wd, ln, et, np, pages, layout, nodes, attrs, regions, text, ord, raw, tmp, fr, gp, hc)
	if model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, mst) != 0 {
		return 3
	}
	json.JsEmit(t, 1, nodes, attrs, regions, text, pages, ledger, layout)
	return 0
}

